-- 기존 객체의 데이터와 OID를 보존하며 이름과 RLS 문맥만 전환한다.
ALTER TABLE magi_schema_versions RENAME TO schema_versions;
ALTER TABLE magi_projects RENAME TO projects;
ALTER TABLE magi_jobs RENAME TO jobs;
ALTER TABLE magi_executions RENAME TO executions;
ALTER TABLE magi_snapshots RENAME TO snapshots;
ALTER TABLE magi_artifacts RENAME TO artifacts;
ALTER TABLE magi_nodes RENAME TO nodes;
ALTER TABLE magi_edges RENAME TO edges;
ALTER TABLE magi_models RENAME TO models;
ALTER TABLE magi_embedding_queue RENAME TO embedding_queue;
ALTER TABLE magi_embeddings RENAME TO embeddings;
ALTER TABLE magi_chunk_sets RENAME TO chunk_sets;
ALTER TABLE magi_chunks RENAME TO chunks;
ALTER TABLE magi_chunk_vectors RENAME TO chunk_vectors;
ALTER TABLE magi_deleted_jobs RENAME TO deleted_jobs;
ALTER TABLE magi_cleanup_commits RENAME TO cleanup_commits;
ALTER TABLE magi_deleted_nodes RENAME TO deleted_nodes;
ALTER TABLE magi_users RENAME TO users;
ALTER TABLE magi_sessions RENAME TO sessions;
ALTER TABLE magi_login_states RENAME TO login_states;
ALTER TABLE magi_service_lease RENAME TO service_lease;
ALTER TABLE magi_daily_usage RENAME TO daily_usage;
ALTER TABLE magi_cost_calls RENAME TO cost_calls;
ALTER TABLE magi_admissions RENAME TO admissions;
ALTER TABLE magi_admin_audit RENAME TO admin_audit;
ALTER TABLE magi_service_settings RENAME TO service_settings;
ALTER TABLE magi_request_windows RENAME TO request_windows;
DO $$
DECLARE obj record;
BEGIN
 FOR obj IN SELECT c.conname,t.relname FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname=current_schema() AND t.relname=ANY(ARRAY['schema_versions','projects','jobs','executions','snapshots','artifacts','nodes','edges','models','embedding_queue','embeddings','chunk_sets','chunks','chunk_vectors','deleted_jobs','cleanup_commits','deleted_nodes','users','sessions','login_states','service_lease','daily_usage','cost_calls','admissions','admin_audit','service_settings','request_windows']) AND c.conname LIKE 'magi\_%' ESCAPE '\' LOOP
  EXECUTE format('ALTER TABLE %I RENAME CONSTRAINT %I TO %I',obj.relname,obj.conname,substring(obj.conname from 6));
 END LOOP;
 FOR obj IN SELECT c.relname,c.relkind FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=current_schema() AND c.relname LIKE 'magi\_%' ESCAPE '\' AND (c.relkind='i' AND EXISTS(SELECT 1 FROM pg_index i JOIN pg_class t ON t.oid=i.indrelid WHERE i.indexrelid=c.oid AND t.relname=ANY(ARRAY['schema_versions','projects','jobs','executions','snapshots','artifacts','nodes','edges','models','embedding_queue','embeddings','chunk_sets','chunks','chunk_vectors','deleted_jobs','cleanup_commits','deleted_nodes','users','sessions','login_states','service_lease','daily_usage','cost_calls','admissions','admin_audit','service_settings','request_windows'])) OR c.relkind='S' AND EXISTS(SELECT 1 FROM pg_depend d JOIN pg_class t ON t.oid=d.refobjid WHERE d.objid=c.oid AND t.relname=ANY(ARRAY['schema_versions','projects','jobs','executions','snapshots','artifacts','nodes','edges','models','embedding_queue','embeddings','chunk_sets','chunks','chunk_vectors','deleted_jobs','cleanup_commits','deleted_nodes','users','sessions','login_states','service_lease','daily_usage','cost_calls','admissions','admin_audit','service_settings','request_windows']))) LOOP
  EXECUTE format('ALTER %s %I RENAME TO %I',CASE WHEN obj.relkind='i' THEN 'INDEX' ELSE 'SEQUENCE' END,obj.relname,substring(obj.relname from 6));
 END LOOP;
END $$;
ALTER POLICY magi_owner ON jobs RENAME TO owner;
ALTER POLICY owner ON jobs USING (current_setting('app.internal',true)='on' OR owner_id=current_setting('app.actor',true)) WITH CHECK (current_setting('app.internal',true)='on' OR owner_id=current_setting('app.actor',true));
ALTER POLICY magi_owner ON executions RENAME TO owner;
ALTER POLICY owner ON executions USING (current_setting('app.internal',true)='on' OR EXISTS(SELECT 1 FROM jobs j WHERE j.id=job_id)) WITH CHECK (current_setting('app.internal',true)='on' OR EXISTS(SELECT 1 FROM jobs j WHERE j.id=job_id));
ALTER POLICY magi_owner ON snapshots RENAME TO owner;
ALTER POLICY owner ON snapshots USING (current_setting('app.internal',true)='on' OR EXISTS(SELECT 1 FROM jobs j WHERE j.id=job_id)) WITH CHECK (current_setting('app.internal',true)='on' OR EXISTS(SELECT 1 FROM jobs j WHERE j.id=job_id));
ALTER POLICY magi_owner ON artifacts RENAME TO owner;
ALTER POLICY owner ON artifacts USING (current_setting('app.internal',true)='on' OR EXISTS(SELECT 1 FROM jobs j WHERE j.id=job_id)) WITH CHECK (current_setting('app.internal',true)='on' OR EXISTS(SELECT 1 FROM jobs j WHERE j.id=job_id));
ALTER POLICY magi_owner ON nodes RENAME TO owner;
ALTER POLICY owner ON nodes USING (current_setting('app.internal',true)='on' OR EXISTS(SELECT 1 FROM jobs j WHERE j.id=job_id)) WITH CHECK (current_setting('app.internal',true)='on' OR EXISTS(SELECT 1 FROM jobs j WHERE j.id=job_id));
ALTER POLICY magi_owner ON edges RENAME TO owner;
ALTER POLICY owner ON edges USING (current_setting('app.internal',true)='on' OR (EXISTS(SELECT 1 FROM nodes n WHERE n.id=source) AND EXISTS(SELECT 1 FROM nodes n WHERE n.id=target))) WITH CHECK (current_setting('app.internal',true)='on' OR (EXISTS(SELECT 1 FROM nodes n WHERE n.id=source) AND EXISTS(SELECT 1 FROM nodes n WHERE n.id=target)));
ALTER POLICY magi_owner ON chunks RENAME TO owner;
ALTER POLICY owner ON chunks USING (current_setting('app.internal',true)='on' OR EXISTS(SELECT 1 FROM nodes n WHERE n.id=node_id)) WITH CHECK (current_setting('app.internal',true)='on' OR EXISTS(SELECT 1 FROM nodes n WHERE n.id=node_id));
ALTER POLICY magi_owner ON chunk_sets RENAME TO owner;
ALTER POLICY owner ON chunk_sets USING (current_setting('app.internal',true)='on' OR EXISTS(SELECT 1 FROM nodes n WHERE n.id=node_id)) WITH CHECK (current_setting('app.internal',true)='on' OR EXISTS(SELECT 1 FROM nodes n WHERE n.id=node_id));
ALTER POLICY magi_owner ON chunk_vectors RENAME TO owner;
ALTER POLICY owner ON chunk_vectors USING (current_setting('app.internal',true)='on' OR EXISTS(SELECT 1 FROM chunks c WHERE c.id=chunk_id)) WITH CHECK (current_setting('app.internal',true)='on' OR EXISTS(SELECT 1 FROM chunks c WHERE c.id=chunk_id));
ALTER POLICY magi_owner ON embeddings RENAME TO owner;
ALTER POLICY owner ON embeddings USING (current_setting('app.internal',true)='on' OR EXISTS(SELECT 1 FROM nodes n WHERE n.id=node_id)) WITH CHECK (current_setting('app.internal',true)='on' OR EXISTS(SELECT 1 FROM nodes n WHERE n.id=node_id));
ALTER POLICY magi_owner ON embedding_queue RENAME TO owner;
ALTER POLICY owner ON embedding_queue USING (current_setting('app.internal',true)='on' OR EXISTS(SELECT 1 FROM nodes n WHERE n.id=node_id)) WITH CHECK (current_setting('app.internal',true)='on' OR EXISTS(SELECT 1 FROM nodes n WHERE n.id=node_id));
